INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT381', 'appropriateness', 150, 'Expansion scenario 150: Consent, Autonomy & Confidentiality', 'Priya is present when a peer has copied another student’s signature on a training form. The matter is not an emergency and a qualified clinician can arrange a private conversation.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice', 'Diamond', 'alert the qualified clinician to the patient’s expressed preference and ask whether they can speak with the patient privately', '', '', '', 'A very appropriate thing to do', 'First, identify the central professional duty: Consent, Autonomy & Confidentiality. The action is assessed for what it actually does, not for imagined later steps. It is very appropriate because it is proportionate, stays within the student’s role and directly protects the relevant person or process. A weaker response may have some benefit, but it would delay, assume or leave a material gap. The unsafe option avoids the central duty and would not be appropriate.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT383', 'appropriateness', 151, 'Expansion scenario 151: Communication & Compassion', 'Quinn sees that a teammate repeatedly leaves all administrative work to one person. They cannot resolve the underlying problem alone, but can listen and bring in the right person.', 'Communication & Compassion', 'Communicate with compassion', 'Diamond', 'acknowledge the person’s concern without making promises, then find an appropriate qualified colleague to help', '', '', '', 'A very appropriate thing to do', 'First, identify the central professional duty: Communication & Compassion. The action is assessed for what it actually does, not for imagined later steps. It is very appropriate because it is proportionate, stays within the student’s role and directly protects the relevant person or process. A weaker response may have some benefit, but it would delay, assume or leave a material gap. The unsafe option avoids the central duty and would not be appropriate.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT385', 'appropriateness', 152, 'Expansion scenario 152: Teamwork & Colleague Concerns', 'Ravi observes that a colleague appears exhausted and is struggling to follow instructions. The behaviour has continued after an earlier respectful prompt.', 'Teamwork & Colleague Concerns', 'Respect colleagues', 'Diamond', 'address the immediate concern and ensure that the supervisor receives a factual account of the repeated pattern', '', '', '', 'A very appropriate thing to do', 'First, identify the central professional duty: Teamwork & Colleague Concerns. The action is assessed for what it actually does, not for imagined later steps. It is very appropriate because it is proportionate, stays within the student’s role and directly protects the relevant person or process. A weaker response may have some benefit, but it would delay, assume or leave a material gap. The unsafe option avoids the central duty and would not be appropriate.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT387', 'appropriateness', 153, 'Expansion scenario 153: Competence & Supervision', 'Sofia is asked to a peer is using a personal account to answer a current patient’s message. They are not trained or authorised to complete the task independently, and suitable supervision is available.', 'Competence & Supervision', 'Know limits', 'Diamond', 'explain the limit clearly and ask the supervisor to demonstrate, supervise or reassign the task', '', '', '', 'A very appropriate thing to do', 'First, identify the central professional duty: Competence & Supervision. The action is assessed for what it actually does, not for imagined later steps. It is very appropriate because it is proportionate, stays within the student’s role and directly protects the relevant person or process. A weaker response may have some benefit, but it would delay, assume or leave a material gap. The unsafe option avoids the central duty and would not be appropriate.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT389', 'appropriateness', 154, 'Expansion scenario 154: Professional Boundaries & Fairness', 'Theo becomes aware that a relative repeatedly answers despite the patient trying to speak. A formal and impartial route is available, and the student has enough factual information to seek guidance.', 'Professional Boundaries & Fairness', 'Stay fair and professional', 'Diamond', 'maintain professional boundaries and use an impartial route to obtain advice or correct the unfairness', '', '', '', 'A very appropriate thing to do', 'First, identify the central professional duty: Professional Boundaries & Fairness. The action is assessed for what it actually does, not for imagined later steps. It is very appropriate because it is proportionate, stays within the student’s role and directly protects the relevant person or process. A weaker response may have some benefit, but it would delay, assume or leave a material gap. The unsafe option avoids the central duty and would not be appropriate.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT391', 'appropriateness', 155, 'Expansion scenario 155: Health, Wellbeing & Fitness to Practise', 'Uma notices that a student is asked to use equipment they have only watched once. The person is due to take part in patient-facing work, and a supervisor can arrange support and safer duties.', 'Health, Wellbeing & Fitness to Practise', 'Safety first', 'Diamond', 'raise the factual fitness concern promptly with the supervisor and help arrange immediate safe cover', '', '', '', 'A very appropriate thing to do', 'First, identify the central professional duty: Health, Wellbeing & Fitness to Practise. The action is assessed for what it actually does, not for imagined later steps. It is very appropriate because it is proportionate, stays within the student’s role and directly protects the relevant person or process. A weaker response may have some benefit, but it would delay, assume or leave a material gap. The unsafe option avoids the central duty and would not be appropriate.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT393', 'appropriateness', 156, 'Expansion scenario 156: Safety & Escalation', 'During a patient-facing session, Victor notices that an interpreter has not been arranged for a sensitive discussion. A qualified supervisor is nearby, but intervening may briefly delay the appointment.', 'Safety & Escalation', 'Safety first', 'Diamond', 'state the observed facts promptly to the supervisor and ask them to check before care continues', '', '', '', 'A very appropriate thing to do', 'First, identify the central professional duty: Safety & Escalation. The action is assessed for what it actually does, not for imagined later steps. It is very appropriate because it is proportionate, stays within the student’s role and directly protects the relevant person or process. A weaker response may have some benefit, but it would delay, assume or leave a material gap. The unsafe option avoids the central duty and would not be appropriate.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT395', 'appropriateness', 157, 'Expansion scenario 157: Honesty & Accurate Records', 'Willow notices that a record or form contains a senior asks the student not to report a near miss. The entry can be corrected transparently and the system retains an audit trail.', 'Honesty & Accurate Records', 'Be honest', 'Diamond', 'preserve the original entry, make the approved correction and tell the responsible supervisor what happened', '', '', '', 'A very appropriate thing to do', 'First, identify the central professional duty: Honesty & Accurate Records. The action is assessed for what it actually does, not for imagined later steps. It is very appropriate because it is proportionate, stays within the student’s role and directly protects the relevant person or process. A weaker response may have some benefit, but it would delay, assume or leave a material gap. The unsafe option avoids the central duty and would not be appropriate.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT397', 'appropriateness', 158, 'Expansion scenario 158: Consent, Autonomy & Confidentiality', 'Xavier is present when a patient states clearly that they do not want an intervention. The matter is not an emergency and a qualified clinician can arrange a private conversation.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice', 'Diamond', 'alert the qualified clinician to the patient’s expressed preference and ask whether they can speak with the patient privately', '', '', '', 'A very appropriate thing to do', 'First, identify the central professional duty: Consent, Autonomy & Confidentiality. The action is assessed for what it actually does, not for imagined later steps. It is very appropriate because it is proportionate, stays within the student’s role and directly protects the relevant person or process. A weaker response may have some benefit, but it would delay, assume or leave a material gap. The unsafe option avoids the central duty and would not be appropriate.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT399', 'appropriateness', 159, 'Expansion scenario 159: Communication & Compassion', 'Yasmin sees that an applicant is being given priority because they know the organiser. They cannot resolve the underlying problem alone, but can listen and bring in the right person.', 'Communication & Compassion', 'Communicate with compassion', 'Diamond', 'acknowledge the person’s concern without making promises, then find an appropriate qualified colleague to help', '', '', '', 'A very appropriate thing to do', 'First, identify the central professional duty: Communication & Compassion. The action is assessed for what it actually does, not for imagined later steps. It is very appropriate because it is proportionate, stays within the student’s role and directly protects the relevant person or process. A weaker response may have some benefit, but it would delay, assume or leave a material gap. The unsafe option avoids the central duty and would not be appropriate.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT002', 'importance', 1, 'Unattended Record', 'During a clinic placement, Leila notices that a computer in an empty consultation room displays an identifiable patient record. She does not know who left it open. Other students and visitors could enter the room.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT004', 'importance', 2, 'Difficult Feedback', 'After a clinical-skills session, Arun finds his peer Mei crying. A tutor criticised Mei’s communication abruptly in front of the group. Arun did not hear the whole exchange.', 'Communication & Compassion', 'Listen carefully, communicate honestly and respond with empathy.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT006', 'importance', 3, 'Repeated Lateness', 'One member of a student project, Joel, has arrived late to three meetings. He completes good work afterwards, but the group repeatedly has to revisit decisions made before he arrived.', 'Teamwork & Colleague Concerns', 'Work constructively, challenge respectfully and communicate early.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT008', 'importance', 4, 'Photographing a Display', 'Nadia sees an unusual clinical image displayed on a staff-room teaching board. A patient number and date of birth are visible. She thinks it would be useful for revision.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT010', 'importance', 5, 'Missing Identification', 'On arrival for placement, Tomas realises he has forgotten the identification badge that local instructions require students to display. The placement office opens in ten minutes.', 'Teamwork & Colleague Concerns', 'Work constructively, challenge respectfully and communicate early.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT012', 'importance', 6, 'Offensive Joke', 'During a break, a student makes a joke about people with a particular disability. One colleague looks uncomfortable but says nothing.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT014', 'importance', 7, 'Unfamiliar Task', 'A busy clinician asks Farah, a first-year student, to perform a task she has observed once but has never been trained or assessed to perform. The clinician begins to leave the room.', 'Competence & Supervision', 'Know limits, work within competence and obtain appropriate supervision.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT016', 'importance', 8, 'Attendance Signature', 'Owen’s friend missed a compulsory teaching session and asks Owen to sign the attendance sheet beside her name. She says she will watch the recording that evening.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT018', 'importance', 9, 'Request for a Diagnosis', 'A patient asks student Hana, “Does this result mean I have cancer?” Hana does not know how to interpret the result, and the supervising doctor is nearby.', 'Competence & Supervision', 'Know limits, work within competence and obtain appropriate supervision.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT020', 'importance', 10, 'Delayed Train', 'Kai’s train stops unexpectedly. He expects to arrive approximately ten minutes late for placement and has the placement administrator’s contact details.', 'Teamwork & Colleague Concerns', 'Work constructively, challenge respectfully and communicate early.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT023', 'importance', 11, 'Wrong Patient Label', 'Mina sees a nurse preparing to carry medicine into Bay 2. The label displays the name of a patient in Bay 4. Mina is a student and does not know whether there is an explanation.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT026', 'importance', 12, 'Corrected Observation', 'After submitting a practical record, Elias notices that he entered 38 instead of 83. His peer suggests replacing the number without recording that it was corrected.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT029', 'importance', 13, 'Relative’s Questions', 'A patient has asked staff not to discuss her condition with relatives. Her brother approaches student Priya and says he is frightened, asking what the tests showed.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT032', 'importance', 14, 'Student Presence Refused', 'Before an examination, a patient says she does not want student Ben in the room. Ben has waited all morning for this learning opportunity.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT035', 'importance', 15, 'Angry About Waiting', 'A patient who has waited two hours tells student Safa that the service is “completely useless.” Safa cannot control the schedule but can contact the receptionist.', 'Communication & Compassion', 'Listen carefully, communicate honestly and respond with empathy.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT038', 'importance', 16, 'Overwhelmed Peer', 'Dev, normally reliable, tells student Amina that he is struggling to concentrate and has made several small administrative errors this week. He looks exhausted.', 'Health, Wellbeing & Fitness to Practise', 'Recognise when wellbeing or impairment affects safe practice and act early.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT041', 'importance', 17, 'Concern Dismissed', 'Student Caleb notices that two people with similar names have documents placed in the same tray. His supervisor replies, “It will be fine,” without checking and walks away.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT044', 'importance', 18, 'Unsupervised Dental Task', 'Dental student Rosa is asked to begin a procedure she has practised only on a model. Her supervisor says he will “be back soon” but gives no time.', 'Competence & Supervision', 'Know limits, work within competence and obtain appropriate supervision.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT047', 'importance', 19, 'Discriminatory Remark', 'A patient tells student Musa that he does not want to be helped by a staff member because of her ethnicity. The staff member hears this and looks upset. There is no immediate emergency.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT050', 'importance', 20, 'A Small Gift', 'At the end of placement, a patient offers student Lina a sealed box of chocolates worth about £5 and says it is to thank the whole student team. Local guidance allows small shared gifts but requires staff to be told.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT053', 'importance', 21, 'Too Tired to Concentrate', 'After choosing to stay out for most of the night, Marcus arrives for placement severely tired. He struggles to follow a routine instruction and is due to observe and assist with patient care. He says coffee will be enough and worries that admitting why he is tired will make him look irresponsible. No patient is currently in danger, but a supervisor can adjust his activities and assess whether he is fit to participate.', 'Health, Wellbeing & Fitness to Practise', 'Recognise when wellbeing or impairment affects safe practice and act early.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT056', 'importance', 22, 'Copied Paragraphs', 'Before a group assignment is submitted, Keira discovers that her friend has pasted several unattributed paragraphs from a website. The friend says there is no time to rewrite them and argues that the information is accurate. Every group member’s name will appear on the submission. The deadline is the next morning, and the tutor can authorise an extension but would need an honest explanation of the problem.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT059', 'importance', 23, 'Wrong Email Recipient', 'Student Noor receives an email containing another student’s confidential support information. The sender appears to have selected the wrong address. Noor has not opened the attachment, but the subject line reveals its general purpose. She can contact the sender and the university support office. The email system allows messages to be deleted locally, although Noor does not know whether that removes the sender’s copy or the record of the error.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT062', 'importance', 24, 'Anonymous Case Online', 'Student Theo drafts a public post about a ‘fascinating case’. He removes the patient’s name but includes a rare condition, approximate age, clinic and date. He has not asked the patient or supervisor for permission and has not published anything yet. Theo believes each detail is harmless on its own and plans to use the post for education rather than entertainment, but people from the local community may recognise the combination.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT065', 'importance', 25, 'Young Relative Interpreting', 'A patient with limited English is being asked to agree to an important but non-emergency procedure. Her 13-year-old son offers to interpret and says he often helps at home. The patient nods but has not been asked privately whether she is comfortable discussing sensitive information through him. A professional telephone interpreting service is available after a short wait, and the procedure does not need to begin before then.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT067', 'importance', 26, 'Missing Research Values', 'Three measurements are missing from a student research project. The submission deadline is tomorrow, and repeating the experiment is impossible in time. The other results are complete, but the missing values may affect the strength of the conclusion. The marking guidance allows limitations to be reported, and the supervisor is available by email. A group member suggests estimating values from the surrounding results so the table appears complete.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT068', 'importance', 26, 'Missing Research Values', 'Three measurements are missing from a student research project. The submission deadline is tomorrow, and repeating the experiment is impossible in time. The other results are complete, but the missing values may affect the strength of the conclusion. The marking guidance allows limitations to be reported, and the supervisor is available by email. A group member suggests estimating values from the surrounding results so the table appears complete.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT070', 'importance', 27, 'Instrument Marking', 'Before a dental procedure, Imani notices that one packaged instrument carries a label stating that it has not completed the required processing cycle. She is unsure whether the label is current because another date is partly obscured. The patient and team are ready, and setting the instrument aside may delay the procedure. A supervisor can verify its status, and another sealed instrument may be available in a nearby room.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT071', 'importance', 27, 'Instrument Marking', 'Before a dental procedure, Imani notices that one packaged instrument carries a label stating that it has not completed the required processing cycle. She is unsure whether the label is current because another date is partly obscured. The patient and team are ready, and setting the instrument aside may delay the procedure. A supervisor can verify its status, and another sealed instrument may be available in a nearby room.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT073', 'importance', 28, 'Repeated Mockery', 'For several weeks, a student has mocked Asha’s accent during group teaching. Asha previously asked him to stop. He repeats it today while several others laugh, and Asha leaves the room. The tutor did not hear the comment, but two students can describe what happened. Asha has not asked anyone to make a formal report, and her peers are unsure whether to speak to her first or act immediately.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT074', 'importance', 28, 'Repeated Mockery', 'For several weeks, a student has mocked Asha’s accent during group teaching. Asha previously asked him to stop. He repeats it today while several others laugh, and Asha leaves the room. The tutor did not hear the comment, but two students can describe what happened. Asha has not asked anyone to make a formal report, and her peers are unsure whether to speak to her first or act immediately.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT076', 'importance', 29, 'Wrong Appointment Date', 'Student Finn enters a patient’s follow-up appointment under Tuesday instead of Thursday. He notices immediately, before anybody has acted on the entry. The system keeps an audit trail and allows transparent corrections, but Finn worries that recording his mistake will make him look careless. The patient has not yet been sent confirmation, and an administrator is available if Finn is uncertain about the correction process.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT077', 'importance', 29, 'Wrong Appointment Date', 'Student Finn enters a patient’s follow-up appointment under Tuesday instead of Thursday. He notices immediately, before anybody has acted on the entry. The system keeps an audit trail and allows transparent corrections, but Finn worries that recording his mistake will make him look careless. The patient has not yet been sent confirmation, and an administrator is available if Finn is uncertain about the correction process.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT079', 'importance', 30, 'Assessment Panic', 'Just before a practical assessment, Jay tells peer Salma that he cannot breathe properly and wants to leave. He is visibly distressed and has previously seemed mildly nervous before assessments, but never to this degree. Salma has no clinical training and cannot determine whether this is panic or another urgent problem. A tutor is nearby, and Jay asks Salma not to draw attention to him in front of the group.', 'Health, Wellbeing & Fitness to Practise', 'Recognise when wellbeing or impairment affects safe practice and act early.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT080', 'importance', 30, 'Assessment Panic', 'Just before a practical assessment, Jay tells peer Salma that he cannot breathe properly and wants to leave. He is visibly distressed and has previously seemed mildly nervous before assessments, but never to this degree. Salma has no clinical training and cannot determine whether this is panic or another urgent problem. A tutor is nearby, and Jay asks Salma not to draw attention to him in front of the group.', 'Health, Wellbeing & Fitness to Practise', 'Recognise when wellbeing or impairment affects safe practice and act early.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT082', 'importance', 31, 'Possible Impairment', 'Before a patient-facing session, Niko notices that his close friend smells strongly of alcohol, is unsteady and is speaking unusually slowly. She says she took prescribed medication, insists that she is safe to continue and asks him not to tell anyone because the supervisor already doubts her reliability. The first patient is due in ten minutes. Niko is a student and cannot determine the cause of her condition, but a placement supervisor is nearby.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT083', 'importance', 31, 'Possible Impairment', 'Before a patient-facing session, Niko notices that his close friend smells strongly of alcohol, is unsteady and is speaking unusually slowly. She says she took prescribed medication, insists that she is safe to continue and asks him not to tell anyone because the supervisor already doubts her reliability. The first patient is due in ten minutes. Niko is a student and cannot determine the cause of her condition, but a placement supervisor is nearby.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT085', 'importance', 32, 'Shared Resource Credit', 'Four students jointly develop a revision guide using a shared document with a visible edit history. Senior student Adam organises the final layout, uploads the guide under his own name and tells the tutor that he produced it. The tutor publicly praises Adam and offers to feature the guide on the course website. Adam says that the others supplied only rough notes, while the other students believe their contribution was substantial.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT086', 'importance', 32, 'Shared Resource Credit', 'Four students jointly develop a revision guide using a shared document with a visible edit history. Senior student Adam organises the final layout, uploads the guide under his own name and tells the tutor that he produced it. The tutor publicly praises Adam and offers to feature the guide on the course website. Adam says that the others supplied only rough notes, while the other students believe their contribution was substantial.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT088', 'importance', 33, 'Inaccessible Venue', 'Mandatory teaching is moved at short notice to an upstairs room with no lift. Mariam, who uses a wheelchair, tells the organiser that she cannot enter. The organiser says the timetable is crowded and offers to send her another student’s notes afterwards. A different accessible room may be available, but checking would delay the start. The session includes live demonstrations and questions that are not fully captured in the written materials.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT089', 'importance', 33, 'Inaccessible Venue', 'Mandatory teaching is moved at short notice to an upstairs room with no lift. Mariam, who uses a wheelchair, tells the organiser that she cannot enter. The organiser says the timetable is crowded and offers to send her another student’s notes afterwards. A different accessible room may be available, but checking would delay the start. The session includes live demonstrations and questions that are not fully captured in the written materials.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT093', 'importance', 34, 'Omitted Allergy', 'During a busy handover, student Elif notices that a documented severe allergy was not mentioned. The receiving clinician is about to review the patient and may already have opened the electronic record, but Elif cannot see their screen. The clinician giving the handover has moved to the next patient and the rest of the team is listening. Elif is certain that she read the allergy correctly but does not know whether it will affect today’s care.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT097', 'importance', 35, 'Possible Incorrect Dose', 'Student George hears a patient say that the tablets just supplied look different from usual. The patient is still holding them. The chart appears to show a lower dose than the number of tablets supplied, although George is not qualified to determine the correct dose and knows packaging can change. The staff member who supplied them is nearby but busy, and another qualified clinician is available at the desk.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT101', 'importance', 36, 'Copied Signature', 'Peer Luis missed a required supervision meeting and asks Maya to copy the supervisor’s signature from an earlier form. He says the supervisor would probably have signed and that a missing form may prevent him progressing to his next placement. Maya knows Luis usually attends, but she cannot verify what happened at this meeting. Luis says he will ask somebody else if Maya refuses and begs her not to report the request.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT105', 'importance', 37, 'Conversation in a Lift', 'Two staff members discuss a patient’s diagnosis and recent family disagreement in a crowded public lift. They do not say the patient’s name, but mention an uncommon condition, the ward and the patient’s occupation. Student Haris is standing beside them, and several visitors can hear. One visitor appears to recognise the details. Haris is junior to both staff members and the lift will reach their floor in less than a minute.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT109', 'importance', 38, 'Relative as Interpreter', 'A patient’s adult daughter offers to interpret a sensitive discussion. The patient says her daughter usually helps at appointments but looks hesitant when asked whether she agrees today. The daughter answers several questions on the patient’s behalf. A professional telephone interpreter is available after a five-minute wait. The discussion is not an emergency, although delaying it will slightly disrupt the clinic schedule.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT113', 'importance', 39, 'Bereaved Relative', 'A recently bereaved relative asks student Cora why the patient died and says nobody has explained what happened. Cora knows only part of the case and is not authorised to provide a clinical explanation. She is due to assist with another patient in five minutes, while the supervising clinician is dealing with an urgent call. A different qualified team member is present but has not met the relative.', 'Communication & Compassion', 'Listen carefully, communicate honestly and respond with empathy.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT117', 'importance', 40, 'Open Argument', 'During a group placement task, Ava and Sam begin arguing loudly about who failed to complete part of the work. Each has messages that appear to support part of their account. Other team members and two patients can hear, and an urgent task still needs to be completed. Student Leanne is their peer, not the group leader, but is the only person nearby who is not involved in the dispute.', 'Teamwork & Colleague Concerns', 'Work constructively, challenge respectfully and communicate early.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT121', 'importance', 41, 'Pressure to Stay Silent', 'After a near miss, a senior clinician tells student Ibrahim, ‘Nothing happened, so do not mention this. Reporting will only create trouble.’ The patient is currently safe. The local process explicitly includes near misses, and Ibrahim has enough factual information to make a report but does not know why the error occurred. The clinician is also responsible for Ibrahim’s placement assessment and warns that escalating would show poor teamwork.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT125', 'importance', 42, 'Repeated Safety Instruction', 'Students have been told to follow a particular infection-control step before every patient contact. Tara sees the same peer omit it twice after being reminded earlier that day. No patient has shown harm, and the peer says the step is unnecessary for short interactions. A patient is waiting now. Tara can prompt the peer immediately, and the supervisor who gave the original instruction is working nearby.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT129', 'importance', 43, 'Friend Request', 'A person whom student Ellie met during a recent placement sends her a personal social-media friend request. The placement has ended, but the person continues to receive care from the same service. The message thanks Ellie for listening and asks a brief question about whether a symptom is normal. Ellie is not part of the current care team and the service has a professional account for general enquiries.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT133', 'importance', 44, 'Romantic Interest', 'Student Daniel realises that he feels attracted to someone he has met repeatedly during placement. The person is still receiving care from Daniel’s team but is not directly assigned to him. During their last conversation, the person suggested meeting for coffee after the placement. Daniel has not responded or acted on his feelings. He can continue his placement without unnecessary contact and can seek confidential guidance from his supervisor.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT137', 'importance', 45, 'Infectious Symptoms', 'On placement morning, Sophie develops a fever and symptoms of an illness that the supplied placement guidance says requires students to stay away and contact the placement office. She feels capable of travelling and has an assessed learning activity that may be difficult to rearrange. Nobody is relying on her for clinical cover. The office accepts telephone calls and email, but the guidance does not specify which method must be used.', 'Health, Wellbeing & Fitness to Practise', 'Recognise when wellbeing or impairment affects safe practice and act early.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT140', 'importance', 46, 'Stereotyped Allocation', 'During a group task, coordinator Max repeatedly gives all note-taking to the only woman in the group, saying, ‘Women are naturally more organised.’ She has already said that she wants the same clinical practice as everyone else. Max argues that changing roles now will slow the group before its deadline. The other students recognise that the allocation is unequal but are unsure whether she wants them to intervene publicly.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT141', 'importance', 46, 'Stereotyped Allocation', 'During a group task, coordinator Max repeatedly gives all note-taking to the only woman in the group, saying, ‘Women are naturally more organised.’ She has already said that she wants the same clinical practice as everyone else. Max argues that changing roles now will slow the group before its deadline. The other students recognise that the allocation is unequal but are unsure whether she wants them to intervene publicly.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT144', 'importance', 47, 'Anonymous Allegation', 'Student Olivia receives an anonymous message claiming that a named peer attended placement while intoxicated. The message provides one date, a location and a description of unsteady behaviour, but no evidence of the cause. The peer is due in a patient-facing area today. Olivia does not know the anonymous writer or whether the allegation is malicious. A placement supervisor can check current fitness without circulating the accusation widely.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT145', 'importance', 47, 'Anonymous Allegation', 'Student Olivia receives an anonymous message claiming that a named peer attended placement while intoxicated. The message provides one date, a location and a description of unsteady behaviour, but no evidence of the cause. The peer is due in a patient-facing area today. Olivia does not know the anonymous writer or whether the allegation is malicious. A placement supervisor can check current fitness without circulating the accusation widely.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT148', 'importance', 48, 'Missed Deadline', 'Amir misses a coursework deadline because he repeatedly postponed the work. The tutor had reminded the group that extensions are reserved for genuine extenuating circumstances. Amir considers claiming that a family emergency occurred because he believes his work would otherwise receive a penalty. He has completed most of the assignment and can still submit it late. Several classmates have also missed deadlines, but Amir does not know what reasons they gave.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT149', 'importance', 48, 'Missed Deadline', 'Amir misses a coursework deadline because he repeatedly postponed the work. The tutor had reminded the group that extensions are reserved for genuine extenuating circumstances. Amir considers claiming that a family emergency occurred because he believes his work would otherwise receive a penalty. He has completed most of the assignment and can still submit it late. Several classmates have also missed deadlines, but Amir does not know what reasons they gave.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT152', 'importance', 49, 'Request for Secrecy', 'Peer Zain tells Holly that he has a specific plan to harm himself that evening and has access to the means. He makes her promise not to tell anyone, saying that previous contact with services felt unhelpful. They are alone, but Holly can contact urgent support and a trusted adult without leaving Zain. Zain says he will never trust her again if she breaks the promise.', 'Health, Wellbeing & Fitness to Practise', 'Recognise when wellbeing or impairment affects safe practice and act early.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT153', 'importance', 49, 'Request for Secrecy', 'Peer Zain tells Holly that he has a specific plan to harm himself that evening and has access to the means. He makes her promise not to tell anyone, saying that previous contact with services felt unhelpful. They are alone, but Holly can contact urgent support and a trusted adult without leaving Zain. Zain says he will never trust her again if she breaks the promise.', 'Health, Wellbeing & Fitness to Practise', 'Recognise when wellbeing or impairment affects safe practice and act early.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT156', 'importance', 50, 'Limited Teaching Places', 'There are ten places at a specialist workshop and twenty eligible students. Organiser Riya must recommend an allocation method. Existing rules give nobody automatic priority, although several applicants say the workshop is particularly relevant to gaps in their experience. The decision must be made quickly, recorded and explained to unsuccessful applicants. Riya knows some applicants personally, and no appeal process has yet been specified.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT157', 'importance', 50, 'Limited Teaching Places', 'There are ten places at a specialist workshop and twenty eligible students. Organiser Riya must recommend an allocation method. Existing rules give nobody automatic priority, although several applicants say the workshop is particularly relevant to gaps in their experience. The decision must be made quickly, recorded and explained to unsuccessful applicants. Riya knows some applicants personally, and no appeal process has yet been specified.', 'Professional Boundaries & Fairness', 'Maintain fair, respectful, non-discriminatory professional boundaries.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT160', 'importance', 51, 'Wrong-side Near Miss', 'During preparation, the team briefly marks the wrong side on a planning sheet. A routine final check catches the error before the patient enters, and the sheet is corrected transparently. One team member says no further discussion is needed because the safety system worked and no harm occurred. Another says the cause should be reviewed because the same unclear abbreviation appears on several blank forms.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT161', 'importance', 51, 'Wrong-side Near Miss', 'During preparation, the team briefly marks the wrong side on a planning sheet. A routine final check catches the error before the patient enters, and the sheet is corrected transparently. One team member says no further discussion is needed because the safety system worked and no harm occurred. Another says the cause should be reviewed because the same unclear abbreviation appears on several blank forms.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT164', 'importance', 52, 'Online Test Answers', 'Several friends invite student Rebecca into a private chat where they are sharing answers during an individual online test. The test is still running. Rebecca sees filenames suggesting that answer images are attached but has not opened them. If she leaves immediately, messages may be deleted; if she remains, more answers may appear automatically. The institution provides a confidential route for reporting suspected assessment misconduct.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT165', 'importance', 52, 'Online Test Answers', 'Several friends invite student Rebecca into a private chat where they are sharing answers during an individual online test. The test is still running. Rebecca sees filenames suggesting that answer images are attached but has not opened them. If she leaves immediately, messages may be deleted; if she remains, more answers may appear automatically. The institution provides a confidential route for reporting suspected assessment misconduct.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT168', 'importance', 53, 'Patient Complaint', 'A patient tells student Idris that a clinician dismissed her concern and laughed. Idris did not witness the consultation and has previously found the clinician considerate. The patient is upset and wants to know how to complain but does not ask Idris to decide whether misconduct occurred. The service has a formal complaints route, and Idris can find a staff member who can explain it privately.', 'Communication & Compassion', 'Listen carefully, communicate honestly and respond with empathy.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT169', 'importance', 53, 'Patient Complaint', 'A patient tells student Idris that a clinician dismissed her concern and laughed. Idris did not witness the consultation and has previously found the clinician considerate. The patient is upset and wants to know how to complain but does not ask Idris to decide whether misconduct occurred. The service has a formal complaints route, and Idris can find a staff member who can explain it privately.', 'Communication & Compassion', 'Listen carefully, communicate honestly and respond with empathy.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT173', 'importance', 54, 'Sharps Injury', 'While clearing equipment under supervision, student Beth accidentally punctures her finger with a used sharp object. The placement instructions say to stop work, wash the area and obtain immediate occupational-health assistance. Beth is embarrassed because she had just been reminded to take care. The area also contains equipment that should not be left unattended, but another trained colleague is present and can make it safe.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT174', 'importance', 54, 'Sharps Injury', 'While clearing equipment under supervision, student Beth accidentally punctures her finger with a used sharp object. The placement instructions say to stop work, wash the area and obtain immediate occupational-health assistance. Beth is embarrassed because she had just been reminded to take care. The area also contains equipment that should not be left unattended, but another trained colleague is present and can make it safe.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT178', 'importance', 55, 'Leaked Examination', 'Two days before an examination, Chen receives a file from a friend who says it is the real paper. The first page contains the institution’s current examination title, so Chen closes it without reading further. He cannot know whether it is genuine without opening more of it. The examination office has a confidential reporting address, and Chen suspects that other candidates may already have received the file.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT179', 'importance', 55, 'Leaked Examination', 'Two days before an examination, Chen receives a file from a friend who says it is the real paper. The first page contains the institution’s current examination title, so Chen closes it without reading further. He cannot know whether it is genuine without opening more of it. The examination office has a confidential reporting address, and Chen suspects that other candidates may already have received the file.', 'Honesty & Accurate Records', 'Be honest, preserve accurate records and protect fair processes.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT183', 'importance', 56, 'Impaired Colleague', 'During a busy clinic, usually competent colleague Yara becomes confused, slurs several words and nearly falls. She insists on seeing the next patient and says she only needs water. The cause could be illness, medication or another form of impairment; the student observing her cannot diagnose it. A senior clinician is nearby, and another colleague can cover the next patient while Yara is assessed.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT184', 'importance', 56, 'Impaired Colleague', 'During a busy clinic, usually competent colleague Yara becomes confused, slurs several words and nearly falls. She insists on seeing the next patient and says she only needs water. The cause could be illness, medication or another form of impairment; the student observing her cannot diagnose it. A senior clinician is nearby, and another colleague can cover the next patient while Yara is assessed.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT188', 'importance', 57, 'Family Pressure', 'A patient who is able to make her own decision says she does not want a proposed intervention. Her relatives repeatedly answer for her, say that she must agree and remind her that they provide most of her support at home. The patient becomes quiet when they are present. She has not asked the relatives to decide for her, and the qualified clinician can speak with her privately before any decision is made.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT189', 'importance', 57, 'Family Pressure', 'A patient who is able to make her own decision says she does not want a proposed intervention. Her relatives repeatedly answer for her, say that she must agree and remind her that they provide most of her support at home. The patient becomes quiet when they are present. She has not asked the relatives to decide for her, and the qualified clinician can speak with her privately before any decision is made.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT193', 'importance', 58, 'Research Withdrawal', 'A participant tells student researcher Anya that he wishes to withdraw from a study. The information sheet states that participants may withdraw without giving a reason and explains separately how already collected data will be handled. The participant asks whether withdrawal means that all existing data will automatically be deleted. Anya knows the written process but is unsure whether a specific dataset can still be removed at this stage.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT194', 'importance', 58, 'Research Withdrawal', 'A participant tells student researcher Anya that he wishes to withdraw from a study. The information sheet states that participants may withdraw without giving a reason and explains separately how already collected data will be handled. The participant asks whether withdrawal means that all existing data will automatically be deleted. Anya knows the written process but is unsure whether a specific dataset can still be removed at this stage.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice, privacy, confidentiality and dignity.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT200', 'importance', 59, 'Capstone: Error and Pressure', 'Student Malik discovers that he entered a result in the wrong patient’s record. A treatment decision may have been based on it, but Malik cannot tell from the record. He immediately tells the senior clinician, who says, ‘Correct it quietly. If you report this, you will cause problems for the whole team.’ The local process requires transparent correction and reporting of errors that may have affected care. Another qualified clinician is available, and the patient’s current condition has not yet been checked.', 'Safety & Escalation', 'Safety first; raise concerns promptly and escalate proportionately.
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT202', 'importance', 60, 'Expansion scenario 60: Safety & Escalation', 'During a patient-facing session, Amina notices that a patient’s identity band does not match the paperwork. A qualified supervisor is nearby, but intervening may briefly delay the appointment.', 'Safety & Escalation', 'Safety first', 'Silver', 'whether the concern could affect the patient before the next step of care', '', '', '', 'Very important', 'This consideration is very important because it can change the safe and professionally defensible response. It is not merely background: if it points to a present risk, the student must seek appropriate support rather than rely on reassurance. By contrast, personal awkwardness or inconvenience can shape tone but cannot outweigh the central duty of safety & escalation.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT204', 'importance', 61, 'Expansion scenario 61: Honesty & Accurate Records', 'Ben notices that a record or form contains a distressed patient asks for information that the student is not authorised to give. The entry can be corrected transparently and the system retains an audit trail.', 'Honesty & Accurate Records', 'Be honest', 'Silver', 'whether the inaccurate entry could already have influenced a decision', '', '', '', 'Very important', 'This consideration is very important because it can change the safe and professionally defensible response. It is not merely background: if it points to a present risk, the student must seek appropriate support rather than rely on reassurance. By contrast, personal awkwardness or inconvenience can shape tone but cannot outweigh the central duty of honesty & accurate records.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT206', 'importance', 62, 'Expansion scenario 62: Consent, Autonomy & Confidentiality', 'Chloe is present when a friend asks for access to confidential placement information. The matter is not an emergency and a qualified clinician can arrange a private conversation.', 'Consent, Autonomy & Confidentiality', 'Respect patient choice', 'Silver', 'whether the patient can make the decision and has expressed a view', '', '', '', 'Very important', 'This consideration is very important because it can change the safe and professionally defensible response. It is not merely background: if it points to a present risk, the student must seek appropriate support rather than rely on reassurance. By contrast, personal awkwardness or inconvenience can shape tone but cannot outweigh the central duty of consent, autonomy & confidentiality.') ON CONFLICT (id) DO NOTHING;
INSERT INTO sjt_questions (id, format, scenario_num, scenario_title, scenario, professional_theme, theme_focus, difficulty, question, option_a, option_b, option_c, correct_answer, walkthrough) VALUES ('SJT208', 'importance', 63, 'Expansion scenario 63: Communication & Compassion', 'Dev sees that a patient says a staff member dismissed a serious concern. They cannot resolve the underlying problem alone, but can listen and bring in the right person.', 'Communication & Compassion', 'Communicate with compassion', 'Silver', 'whether the person needs timely help from someone authorised to respond', '', '', '', 'Very important', 'This consideration is very important because it can change the safe and professionally defensible response. It is not merely background: if it points to a present risk, the student must seek appropriate support rather than rely on reassurance. By contrast, personal awkwardness or inconvenience can shape tone but cannot outweigh the central duty of communication & compassion.') ON CONFLICT (id) DO NOTHING;
